// package.json (корень монорепо)
{
  "private": true,
  "workspaces": ["apps/*", "packages/*"],
  "scripts": {
    "dev": "npm run dev --workspace apps/api & npm run dev --workspace apps/web",
    "test": "npm test --workspaces --if-present"
  }
}

# apps/api/.env.example — без реальных значений
DATABASE_URL=postgres://user:password@localhost:5432/app
JWT_SECRET=REPLACE_ME_with_32_plus_random_characters
CLIENT_ORIGIN=http://localhost:5173

# apps/web/.env.example — всё здесь видно в браузере, секретов нет
VITE_API_URL=http://localhost:3000
